function clampInt(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export async function getRandomSongs(options: {
  size: number;
  defaultCoverArt: string;
  cookie?: string;
}): Promise<
  Array<{
    id: string;
    isDir: false;
    title: string;
    artist: string;
    coverArt: string;
  }>
> {
  const size = clampInt(Math.trunc(options.size), 0, 200);
  if (size <= 0) return [];

  const cookie = (options.cookie ?? '').trim() || DEFAULT_NETEASE_COOKIE;
  const { recommend } = await fetchDailyRecommendSongs({ cookie });

  const songs: Array<{
    id: string;
    isDir: false;
    title: string;
    artist: string;
    coverArt: string;
  }> = [];

  for (const raw of recommend) {
    if (songs.length >= size) break;
    const normalized = normalizeDailyRecommendSong(
      raw,
      options.defaultCoverArt
    );
    if (!normalized) continue;
    songs.push(normalized);
  }

  return songs;
}
